document.getElementById('speaking-inquiry').addEventListener('submit',async event=>{event.preventDefault();const form=event.currentTarget,button=form.querySelector('button'),status=document.getElementById('speaking-status');button.disabled=true;status.textContent='Submitting…';try{const response=await fetch('/api/speaking-inquiry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(Object.fromEntries(new FormData(form)))});const data=await response.json();if(!response.ok)throw new Error(data.error||'Unable to submit.');status.textContent='Your inquiry has been received. Reference: '+data.id;form.reset();}catch(error){status.textContent=error.message+' Please retry.';}finally{button.disabled=false;}});